const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-118.423217, 34.770153]);
  const region = point.buffer(300); // 300-meter radius
  const date = '2020-04-14';

  // 2. Data Acquisition - Landsat 8
  let landsatCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  let imageCount = landsatCol.size().getInfo();
  console.log(`Landsat 8 images on ${date}: ${imageCount}`);

  // If no image on exact date, try ±7 days
  if (imageCount === 0) {
    landsatCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(region)
      .filterDate('2020-04-07', '2020-04-21');
    imageCount = landsatCol.size().getInfo();
    console.log(`Landsat 8 images in ±7 days: ${imageCount}`);
  }

  if (imageCount === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get best image (least cloud cover)
  const image = landsatCol.sort('CLOUD_COVER').first();

  // 3. Calculate NDWI (Normalized Difference Water Index)
  const ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

  // 4. Get pixel statistics
  const stats = ndwi.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 30,
    maxPixels: 1e9
  });

  const ndwiMean = stats.get('NDWI_mean').getInfo();
  const pixelCount = stats.get('NDWI_count').getInfo();

  console.log(`NDWI Mean: ${ndwiMean?.toFixed(4)}`);
  console.log(`Valid Pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (ndwiMean === null || ndwiMean === undefined || isNaN(ndwiMean)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Decision logic: Water typically has NDWI > 0, solar farms have NDWI < 0
  // Threshold: NDWI > 0.1 suggests water, NDWI < -0.1 suggests solar farm
  if (ndwiMean > 0.1) {
    console.log("Evidence: High NDWI suggests water body");
    console.log("<answer>B</answer>"); // Not a solar farm (it's water)
  } else if (ndwiMean < -0.1) {
    console.log("Evidence: Low NDWI suggests non-water surface (potential solar farm)");
    console.log("<answer>A</answer>"); // Likely solar farm
  } else {
    console.log("Evidence: Neutral NDWI - inconclusive");
    console.log("<answer>B</answer>"); // Default to not solar farm if uncertain
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
